DO $test$ DECLARE a uuid:=gen_random_uuid();b uuid:=gen_random_uuid();c uuid:=gen_random_uuid();moduser uuid:=gen_random_uuid();roleid uuid;BEGIN
 INSERT INTO auth.users(id) VALUES(a),(b),(c),(moduser);INSERT INTO public.profiles(user_id,account_state) VALUES(a,'active'),(b,'active'),(c,'active'),(moduser,'active');
 INSERT INTO public.user_privacy_settings(user_id,profile_visibility,contact_permission) SELECT v.id,'friends','members' FROM (VALUES(a),(b),(c),(moduser)) v(id);
 INSERT INTO public.user_eligibility(user_id,status,verification_method,verification_version,verified_at) SELECT v.id,'eligible','test','test',now() FROM (VALUES(a),(b),(c),(moduser)) v(id);
 INSERT INTO public.policy_acceptances(user_id,policy_version_id) SELECT v.id,p.id FROM (VALUES(a),(b),(c),(moduser)) v(id) CROSS JOIN public.policy_versions p WHERE p.mandatory AND p.published_at<=now() AND p.retired_at IS NULL;
 INSERT INTO public.friendships(user_low,user_high) VALUES(least(a,b),greatest(a,b));SELECT id INTO roleid FROM public.admin_roles WHERE role_key='moderator';INSERT INTO public.admin_role_assignments(user_id,role_id) VALUES(moduser,roleid);
 PERFORM set_config('test.hide_a',a::text,false);PERFORM set_config('test.hide_b',b::text,false);PERFORM set_config('test.hide_c',c::text,false);PERFORM set_config('test.hide_mod',moduser::text,false);
 IF has_function_privilege('anon','public.hide_own_friend_message(uuid)','EXECUTE') OR has_table_privilege('authenticated','public.messages','UPDATE') THEN RAISE EXCEPTION 'Unsafe privilege';END IF;
END $test$;
SET ROLE authenticated;
SELECT set_config('request.jwt.claim.sub',current_setting('test.hide_a'),false);
SELECT set_config('test.hide_thread',public.start_friend_conversation(current_setting('test.hide_b')::uuid)::text,false);
SELECT set_config('test.hide_message',public.send_friend_message(current_setting('test.hide_thread')::uuid,'Hidden but retained')::text,false);
SELECT set_config('request.jwt.claim.sub',current_setting('test.hide_b'),false);
DO $test$ BEGIN BEGIN PERFORM public.hide_own_friend_message(current_setting('test.hide_message')::uuid);RAISE EXCEPTION 'Recipient hid another message';EXCEPTION WHEN insufficient_privilege THEN NULL;END;END $test$;
SELECT set_config('request.jwt.claim.sub',current_setting('test.hide_c'),false);
DO $test$ BEGIN BEGIN PERFORM public.hide_own_friend_message(current_setting('test.hide_message')::uuid);RAISE EXCEPTION 'Nonparticipant hid a message';EXCEPTION WHEN insufficient_privilege THEN NULL;END;END $test$;
SELECT set_config('request.jwt.claim.sub',current_setting('test.hide_a'),false);
SELECT public.hide_own_friend_message(current_setting('test.hide_message')::uuid);
SELECT public.hide_own_friend_message(current_setting('test.hide_message')::uuid);
DO $test$ BEGIN IF EXISTS(SELECT 1 FROM public.list_friend_messages(current_setting('test.hide_thread')::uuid) WHERE id=current_setting('test.hide_message')::uuid) THEN RAISE EXCEPTION 'Hidden message still in thread';END IF;END $test$;
SELECT set_config('request.jwt.claim.sub',current_setting('test.hide_b'),false);
DO $test$ BEGIN IF EXISTS(SELECT 1 FROM public.list_friend_messages(current_setting('test.hide_thread')::uuid) WHERE id=current_setting('test.hide_message')::uuid) THEN RAISE EXCEPTION 'Hidden message still visible to recipient';END IF;END $test$;
SELECT public.block_user(current_setting('test.hide_a')::uuid);
DO $test$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.list_own_blocked_received_messages() WHERE id=current_setting('test.hide_message')::uuid AND body='Hidden but retained') THEN RAISE EXCEPTION 'Safety evidence missing after block';END IF;END $test$;
SELECT set_config('test.hide_report',public.report_received_friend_message(current_setting('test.hide_message')::uuid,'Concern')::text,false);
SELECT set_config('request.jwt.claim.sub',current_setting('test.hide_mod'),false);
SELECT set_config('request.jwt.claims','{"aal":"aal2"}',false);
DO $test$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.list_direct_message_reports_for_review() WHERE report_id=current_setting('test.hide_report')::uuid AND message_body='Hidden but retained') THEN RAISE EXCEPTION 'Moderator cannot review evidence';END IF;END $test$;
RESET ROLE;
DO $test$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.messages WHERE id=current_setting('test.hide_message')::uuid AND body='Hidden but retained' AND deleted_at IS NOT NULL) THEN RAISE EXCEPTION 'Retained content missing';END IF;END $test$;
